create or replace view v_sales_discrepancies with(security_invoker=true) as select s.shipper_inv_no,s.sales_date,s.product_name,s.invoice_amount_inr from sales_updates s left join shipping_master m on m.shipper_inv_no=s.shipper_inv_no where m.id is null;
create or replace view v_fg_stock with(security_invoker=true) as select p.product_name,greatest(0,coalesce(sum(u.production_qty),0)-coalesce((select sum(s.billed_containers*p.qty_per_container) from sales_updates s where s.product_name=p.product_name),0)-coalesce((select sum(a.qty) from loose_unit_adjustments a where a.product_name=p.product_name and a.action in('Remove','Discard')),0)) fg_units,coalesce(sum(u.complete_small_box_qty),0) small_boxes,coalesce(sum(u.complete_big_box_qty),0) big_boxes,floor(greatest(0,coalesce(sum(u.production_qty),0))/p.qty_per_container) full_containers from products p left join production_updates u on u.product_name=p.product_name group by p.product_name,p.qty_per_container;
create or replace view v_rm_requirements with(security_invoker=true) as select p.product_name,greatest(0,coalesce(sum(l.target_containers*p.qty_per_container),0)-coalesce((select sum(s.billed_containers*p.qty_per_container) from sales_updates s where s.product_name=p.product_name),0)-coalesce((select fg_units from v_fg_stock f where f.product_name=p.product_name),0)) net_production_required, greatest(0,coalesce(sum(l.target_containers*p.qty_per_container),0)-coalesce((select sum(s.billed_containers*p.qty_per_container) from sales_updates s where s.product_name=p.product_name),0)-coalesce((select fg_units from v_fg_stock f where f.product_name=p.product_name),0))*p.unit_weight_gram/1000 rm_kg_required,r.stock_qty from products p left join sales_plan_lines l on l.product_name=p.product_name left join raw_materials r on true group by p.product_name,p.unit_weight_gram,r.stock_qty;
create or replace view v_shipping_mis with(security_invoker=true) as select product,shipper,pod,count(*) shipment_count,coalesce(sum(sea_freight_inv_amount),0) sea_freight,coalesce(sum(other_local_inv_amount),0) local_invoice,coalesce(sum(duty_inv_amount),0) duty,coalesce(sum(sea_freight_inv_amount),0)+coalesce(sum(other_local_inv_amount),0)+coalesce(sum(duty_inv_amount),0) grand_total from shipping_master group by product,shipper,pod;
create or replace view v_container_forecast with(security_invoker=true) as select q.machine_no,q.sequence_no,q.product_name,gs.container_number,(select max(u.production_date) from production_updates u where u.machine_no=q.machine_no and u.product_name=q.product_name) production_ready_date,(select max(u.production_date) from production_updates u where u.machine_no=q.machine_no and u.product_name=q.product_name)+(select (value#>>'{}')::int from app_settings where key='stuffing_buffer_days') stuffing_date from machine_production_queue q cross join lateral generate_series(1,ceil(q.planned_containers)::int) gs(container_number);
create or replace view v_dashboard with(security_invoker=true) as select 'Open sales plans' metric,count(*)::text value from sales_plans union all select 'Production records',count(*)::text from production_updates union all select 'Shipments',count(*)::text from shipping_master union all select 'FG products',count(*)::text from v_fg_stock;
create or replace function weighted_avg_rate(p_item_code text) returns numeric language sql stable security invoker set search_path=public as $$select coalesce(sum(qty_purchased*rate)/nullif(sum(qty_purchased),0),0) from(select qty_purchased,rate from purchases where item_code=p_item_code order by purchase_date desc,id desc limit 7)x$$;
create or replace function upsert_shipping_master(p_data jsonb) returns shipping_master language plpgsql security invoker set search_path=public as $$declare result shipping_master;begin if coalesce(trim(p_data->>'shipper_inv_no'),'')='' then raise exception 'shipper_inv_no is mandatory';end if;insert into shipping_master(shipper_inv_no,shipper_inv_date,shipper,product,pod,pol,eta,etd,container_no,shipping_bill_no,hbl_no,mbl_no,sea_freight_inv_amount,other_local_inv_amount,duty_inv_amount) values(p_data->>'shipper_inv_no',(p_data->>'shipper_inv_date')::date,p_data->>'shipper',p_data->>'product',p_data->>'POD',p_data->>'POL',(p_data->>'ETA')::date,(p_data->>'ETD')::date,p_data->>'container_no',p_data->>'shipping_bill_no',p_data->>'HBL_no',p_data->>'MBL_no',(p_data->>'sea_freight_inv_amount')::numeric,(p_data->>'other_local_inv_amount')::numeric,(p_data->>'duty_inv_amount')::numeric) on conflict(shipper_inv_no) do update set shipper_inv_date=excluded.shipper_inv_date,shipper=excluded.shipper,product=excluded.product,pod=excluded.pod,pol=excluded.pol,eta=excluded.eta,etd=excluded.etd,container_no=excluded.container_no,shipping_bill_no=excluded.shipping_bill_no,hbl_no=excluded.hbl_no,mbl_no=excluded.mbl_no,sea_freight_inv_amount=excluded.sea_freight_inv_amount,other_local_inv_amount=excluded.other_local_inv_amount,duty_inv_amount=excluded.duty_inv_amount,updated_at=now() returning * into result;return result;end $$;

